// --- Prediction tracker: fetch + weighting UI -----------------------------
// Split out of app/index.html as part of the JS-splitting pass. Covers:
// pulling thepredictiontracker.com's CSV through the serverless proxy
// (fetchPredictions() -- same freshness-window-reuse pattern as
// refreshLines() in app/js/odds.js: check the shared tier first, skip the
// real fetch if someone already loaded within the window), and the
// Prediction Systems settings panel (renderSystemsSettings() -- the
// checklist of ~40 systems plus BP/Comp/Vegas core weights,
// setWeight()/bindWeightInput() for the per-system weight boxes,
// systemsPresentThisWeek() to dim systems the current week's CSV didn't
// carry, updateSystemsCount() for the small "N on" / "last loaded" status
// line).
//
// Loaded as a plain <script src="/app/js/prediction-tracker.js"> tag,
// same as the other split files -- an ordinary global scope, not a
// module. Real external references this file makes that are NOT self-
// contained (all resolved lazily inside function bodies, never at top-
// level, so script load order relative to the rest of the page doesn't
// matter for correctness -- same reasoning as the other split files'
// header comments):
//   - `state`, `games` -- global app state and the current week's game
//     list (main inline script).
//   - `PRED_SYSTEMS`/`TOP_SYSTEM_RANKS` -- app/data/pred-systems.js /
//     main inline script (TOP_SYSTEM_RANKS is a small backtest-ranking
//     table, still inline).
//   - `pullTier()` -- cross-device shared-tier sync (main inline script).
//   - `apiFetch()` -- classified fetch wrapper (app/js/api-client.js).
//   - `minsAgo()`/`SHARED_FRESH_MINUTES` -- freshness-window helpers
//     (main inline script).
//   - `applyPredictions()`/`lastPredUnmatched` -- app/js/pdf-import.js.
//   - `renderBoard()` -- app/js/board.js.
//   - `weightOf()` -- app/js/model.js.
//   - `inputsFor()`/`esc()` -- general utilities (main inline script).
//   - `save()` -- persistence (main inline script).
function adoptPredictionsResponseLocally(data){
  if(!data||!Array.isArray(data.games)) return false;
  state.predictions=data.games;
  state.predMeta={fetchedAt:data.fetchedAt||new Date().toISOString(),count:data.count!=null?data.count:data.games.length};
  return true;
}

function setPredictionLoadState(isLoading){
  [document.getElementById('loadPredsBtn'),document.getElementById('loadPredsBtn2')].filter(Boolean).forEach(btn=>{
    if(isLoading){
      if(btn._pgIdleText==null) btn._pgIdleText=btn.textContent;
      btn.disabled=true; if(btn.setAttribute) btn.setAttribute('aria-busy','true'); btn.textContent='Loading predictions…';
    }else{
      btn.disabled=false; if(btn.removeAttribute) btn.removeAttribute('aria-busy');
      if(btn._pgIdleText!=null){ btn.textContent=btn._pgIdleText; delete btn._pgIdleText; }
    }
  });
}
function setPredictionStatus(text,color){
  const el=document.getElementById('predStatus');
  if(!el) return;
  if(color) el.style.color=color;
  el.textContent=text||'';
}

async function fetchPredictions(opts){
  // Same {auto:true} convention as refreshLines() -- button clicks pass a
  // DOM event, which is never mistaken for an automatic load.
  const auto=!!(opts&&opts.auto===true);
  if(typeof betaRememberAction==="function") betaRememberAction("predictions_load",{source:auto?"auto":"button"});
  setPredictionStatus('Loading predictions…','var(--muted)');
  setPredictionLoadState(true);
  try{
    // Freshness guard: pull the shared tier first and skip the real fetch
    // if someone already loaded predictions within the freshness window
    // (see SHARED_FRESH_MINUTES, still in app/index.html's main inline
    // script).
    await pullTier("shared",true);
    const freshAge=minsAgo(state.predMeta&&state.predMeta.fetchedAt);
    if(freshAge!=null&&freshAge<SHARED_FRESH_MINUTES&&Array.isArray(state.predictions)&&state.predictions.length){
      const matched=applyPredictions();
      if(typeof captureModelPerformanceSnapshot==="function") captureModelPerformanceSnapshot();
      renderBoard(); renderSystemsSettings();
      {
        const missing=(typeof lastBoardPredMissing!=="undefined"&&Array.isArray(lastBoardPredMissing))?lastBoardPredMissing.length:0;
        const boardTotal=Array.isArray(games)?games.length:0;
        const poolScoped=(typeof currentPool==="function"&&!!currentPool());
        const matchProblem=poolScoped&&missing>0;
        setPredictionStatus(`Using recent data from ${freshAge}m ago · `
          +(poolScoped&&boardTotal?`${matched}/${boardTotal} pool games matched`:`${matched} matched to board`)
          +(matchProblem?` · ${missing} pool game${missing===1?'':'s'} missing prediction data`:''),
          matchProblem?'var(--amber)':'var(--muted)');
      }
      if(typeof trackBetaEvent==='function'){ trackBetaEvent('predictions_load',{source:'cache'}); trackBetaEvent('predictions_ready'); }
      setPredictionLoadState(false);
      return;
    }
    const result=await apiFetch('/api/fetch_predictions',{});
    if(!result.ok){
      const msg=result.kind==="rate_limit"?"Loaded too recently — the shared predictions are already current, try again in a bit.":result.error;
      throw new Error(msg);
    }
    const data=result.body;
    if(!Array.isArray(data.games)||!data.games.length) throw new Error(data.message||'No prediction rows returned');
    // api/fetch_predictions.py already wrote predictions/predMeta into the
    // shared bucket itself -- adopt that persisted copy rather than
    // building/pushing our own (a generic shared POST is rejected now, see
    // api/state.py).
    const sharedPulled=await pullTier("shared",true);
    // Same resilience rule as odds: if the upstream fetch succeeded but the
    // shared cache write (or our follow-up shared-state read) did not, use
    // the fresh endpoint response locally instead of silently reverting to
    // stale shared data. sharedUpdatedAt intentionally remains untouched.
    if(data.sharedPersisted===false || !sharedPulled || !Array.isArray(state.predictions) || !state.predMeta || state.predMeta.fetchedAt!==data.fetchedAt){
      adoptPredictionsResponseLocally(data);
    }
    const matched=applyPredictions();
    if(typeof captureModelPerformanceSnapshot==="function") captureModelPerformanceSnapshot();
    renderBoard(); renderSystemsSettings();
    // Real reliability gap fix: the server can now legitimately return 200
    // with real (if stale) data even when the LIVE upstream fetch failed
    // (api/fetch_predictions.py's stale-if-error fallback) or when it
    // detected a real data-quality problem worth a manual look (schema-
    // drift `warnings`, e.g. a sharp game-count drop or a core system
    // vanishing). Neither of those is the normal green "all good" case,
    // but neither is a hard failure either -- surfaced as amber, distinct
    // from both.
    {
      const missing=(typeof lastBoardPredMissing!=="undefined"&&Array.isArray(lastBoardPredMissing))?lastBoardPredMissing.length:0;
      const boardTotal=Array.isArray(games)?games.length:0;
      const poolScoped=(typeof currentPool==="function"&&!!currentPool());
      const pgOn=(typeof isPickGaugeModelActive==="function")&&isPickGaugeModelActive();
      const noneOn=!pgOn&&state.enabledSystems.length===0;
      const hasWarnings=Array.isArray(data.warnings)&&data.warnings.length>0;
      if(data.usingStaleFallback){
        setPredictionStatus(`${data.message||'Using last successful predictions (source unavailable).'} · ${matched} matched to board`,'var(--amber)');
        console.warn('[predictions] stale fallback served:',data.message);
      }else{
        const matchText=poolScoped&&boardTotal
          ?`${matched}/${boardTotal} pool games matched`
          :`${matched} matched to board`;
        const matchProblem=poolScoped&&missing>0;
        setPredictionStatus(`loaded ${data.count} games · ${matchText}`
          +(matchProblem?` · ${missing} pool game${missing===1?'':'s'} missing prediction data`:'')
          +(hasWarnings?` · ${data.warnings.length} data-quality warning${data.warnings.length===1?'':'s'}`:'')
          +(noneOn?' · open Models & weights to enable columns':''),
          matched>0?((hasWarnings||matchProblem)?'var(--amber)':'var(--green-text)'):'var(--amber)');
      }
      if(hasWarnings) data.warnings.forEach(w=>console.warn('[predictions] data-quality warning:',w));
    }
    if(typeof trackBetaEvent==='function'){ trackBetaEvent('predictions_load',{source:'server'}); trackBetaEvent('predictions_ready'); }
  }catch(err){
    setPredictionStatus('Predictions failed: '+err.message,'var(--red-text)');
    console.error(err);
  }finally{
    setPredictionLoadState(false);
  }
}
// Settings checklist. Systems present in this week's fetch are enabled-able and
// live; ones the CSV didn't carry this week are shown dimmed but still toggleable
// (they just won't contribute until a fetch includes them).
function systemsPresentThisWeek(){
  const present=new Set();
  (state.predictions||[]).forEach(p=>Object.keys(p.systems||{}).forEach(c=>present.add(c)));
  return present;
}
// One-click PickGauge Model # mode. Enabling it clears the currently selected
// custom/comparison systems so the board immediately presents one standalone
// PickGauge Model # column. The five internal recipe models are NOT written to
// enabledSystems, so they never appear as columns merely because PickGauge is
// on. Afterward, a user may manually enable any individual system below as a
// separate comparison column without changing the PickGauge calculation.
function applyPickGaugeModelPreset(){
  const turningOn=!isPickGaugeModelActive();
  state.pickGaugeModelEnabled=turningOn;
  if(turningOn) state.enabledSystems=[];
  save();
  renderSystemsSettings();
  renderBoard();
  updateSystemsCount();
}

function setWeight(key, raw){
  if(!state.weights) state.weights={};
  const v=parseFloat(raw);
  // "Matches this key's own default -> don't bother storing it" is a
  // sparse-storage optimization, not a behavior change -- but the default
  // isn't a universal 1 (see weightOf()): "pickgauge" (Custom Blend's own
  // weight for the PickGauge number, Option 2, Sept 1 2026) defaults to
  // 3, everything else -- including "vegas" as of Sept 2, 2026, now a
  // real checkbox+weight input like every comparison system rather than
  // a permanently-included, defaults-to-0 special case -- defaults to 1.
  // Comparing against a hardcoded 1 here would silently DELETE a user's
  // explicit "3" for pickgauge (NOT its default -- reducing PickGauge's
  // own weight in the blend is exactly the kind of input this box exists
  // to let someone set) and revert it right back to the wrong default the
  // moment they typed the value they actually wanted.
  const dflt=(key==="pickgauge")?3:1;
  if(raw===""||isNaN(v)||v===dflt){ delete state.weights[key]; }
  else { state.weights[key]=Math.max(0,v); }
  save(); renderBoard();
}
function bindWeightInput(el){
  el.onchange=()=>{ setWeight(el.dataset.w, el.value); el.value=(weightOf(el.dataset.w)); };
}
function renderSystemsSettings(){
  const pgActive=(typeof isPickGaugeModelActive==="function")&&isPickGaugeModelActive();
  // PickGauge Model # is a standalone proprietary blend -- its own numeric
  // weights (the coreWeights box: BP/Comp/Vegas) stay hidden while it's
  // active, since they play no part in the fixed recipe. Comparison
  // systems are different (Option 2, Sept 1 2026): a checked system's
  // weight box now stays VISIBLE while PickGauge is active too, because it
  // controls that system's contribution to Custom Blend (myBlendNumber(),
  // app/js/model.js) even though it still has zero effect on the pure
  // PickGauge Model # number itself.
  const coreWeights=document.getElementById('coreWeights');
  if(coreWeights) coreWeights.style.display=pgActive?"none":"";
  if(!pgActive){
    document.querySelectorAll('.core-weights .weight-inp').forEach(el=>{ el.value=weightOf(el.dataset.w); bindWeightInput(el); });
  }
  // Custom Blend's own weight box (PickGauge's own weight within the blend) --
  // the inverse of coreWeights: only meaningful, so only shown, while
  // PickGauge is active.
  const pgBlendWeights=document.getElementById('pgBlendWeights');
  if(pgBlendWeights) pgBlendWeights.style.display=pgActive?"":"none";
  if(pgActive){
    const pgWeightInp=document.getElementById('cwPickgauge');
    const inp=pgWeightInp?pgWeightInp.querySelector('.weight-inp'):null;
    if(inp){ inp.value=weightOf("pickgauge"); bindWeightInput(inp); }
  }
  const pgBtn=document.getElementById("pickGaugeModelBtn");
  if(pgBtn){
    // A real checkbox is the on/off indicator now (Drew's call, Aug 28 --
    // the previous whole-button background-color swap on .active wasn't
    // an obvious enough "is this on" signal). .checked is the unambiguous
    // source of truth a checkbox already gives for free; no separate
    // active-state class/attribute needed to communicate the same thing
    // a second way.
    pgBtn.checked=pgActive;
    pgBtn.title=pgActive
      ?"PickGauge Model # active — PickGauge’s default blend of five prediction models plus the live market line."
      :"Use PickGauge Model # — PickGauge’s default blend of five prediction models plus the live market line.";
  }
  const enabledCore=new Set(state.enabledSystems);
  // BP/Comp/Vegas's weight boxes only matter when the matching checkbox
  // below is actually on -- weightedModel() skips all three entirely
  // otherwise (see the enabledCore.has(k) gate there), so showing a
  // weight input for an input that isn't counted in Model # right now
  // was pure clutter, and looked like it was doing something it wasn't.
  // Vegas (checkbox added Sept 2, 2026, Drew's explicit request) now
  // follows the exact same pattern as BP/Comp -- previously it had no
  // checkbox anywhere in this panel and stayed permanently included at a
  // default weight of 0 (an easy-to-miss "opt in by raising the number"
  // design); it's now an explicit, deliberate on/off toggle like every
  // other input, available in BOTH the fully-custom Model # and Custom Blend
  // (see weightedModel()/myBlendNumber(), app/js/model.js).
  const cwBp=document.getElementById("cwBp"); if(cwBp) cwBp.style.display=enabledCore.has("bp")?"":"none";
  const cwComp=document.getElementById("cwComp"); if(cwComp) cwComp.style.display=enabledCore.has("comp")?"":"none";
  const wrap=document.getElementById("systemsList");
  if(!wrap) return;
  const present=systemsPresentThisWeek();
  const enabled=enabledCore;
  const knownCodes=PRED_SYSTEMS.map(s=>s.code);
  const extras=[...present].filter(c=>!knownCodes.includes(c)).sort();
  const all=[...PRED_SYSTEMS, ...extras.map(c=>({code:c,name:c}))];
  // Only Drew's own curated subset shows as a checkbox (see
  // FEATURED_SYSTEM_CODES, app/data/pred-systems.js) -- there is no UI
  // path to browse or enable anything outside it anymore (the old "Show
  // all N available systems" toggle was removed at Drew's request).
  // Ingestion itself is unchanged: a real sheet can still supply any
  // system code, and if one is already enabled (from before this change,
  // or because a future session re-adds a browse path) it still counts
  // toward Model # and its row still renders here via the
  // `enabled.has(s.code)` escape hatch below -- deliberate, so an
  // enabled-but-not-featured system can never become an invisible-but-
  // active toggle with no visible checkbox to turn it back off.
  const featuredSet=(typeof FEATURED_SYSTEM_CODES!=="undefined")?FEATURED_SYSTEM_CODES:null;
  const visibleAll=all.filter(s=>!featuredSet||featuredSet.has(s.code)||enabled.has(s.code));
  const core=[
    {code:"bp",name:"Brad Powers"},
    // Import Powers PDF lives HERE now -- as its own grid cell immediately
    // after BP's checklist item, not a separate button up in the
    // core-weights box (see app/index.html's INPUT WEIGHTS box, which no
    // longer has it). Handled as a special-cased non-checkbox item in the
    // .map() below rather than a real system, since it isn't one.
    {code:"__import_pdf__"},
    {code:"comp",name:"Computer Line"},
    // Vegas (live line) -- added as a real checkbox item Sept 2, 2026,
    // Drew's explicit request ("I still don't see functionality for
    // anyone to incorporate the live vegas line as part of their model
    // #"). Grouped with BP/Comp at the top of the grid rather than mixed
    // in among the prediction-tracker systems below, since -- like
    // BP/Comp -- it isn't one of those systems and needs its own "has"/
    // badge handling (a live market line, not a CSV/PDF column).
    {code:"vegas",name:"Market (live line)"},
  ];
  wrap.innerHTML=[...core,...visibleAll].map(s=>{
    if(s.code==="__import_pdf__"){
      return `<div class="sys-item sys-item-action">
        <label class="btn btn-secondary" id="pdfImportLabel" style="cursor:pointer;padding:4px 9px;font-size:12.5px;">${typeof pgIcon==="function"?pgIcon("upload"):""} Import Powers PDF<input type="file" id="pdfFile" accept="application/pdf" style="display:none;"></label>
        <span id="pdfStatus" class="mono-sm" role="status" aria-live="polite"></span>
      </div>`;
    }
    const on=enabled.has(s.code);
    const isCore=s.code==="bp"||s.code==="comp";
    const idx=s.code==="bp"?0:1;
    const has=s.code==="vegas"
      ? games.some(g=>(typeof pickGaugeModelMarketLine==="function"?pickGaugeModelMarketLine(g):g.vegas)!=null)
      : (isCore?games.some(g=>{const v=inputsFor(g.key)[idx]; return v!=null&&v!=="";}):present.has(s.code));
    const dim=(!has&&(isCore||s.code==="vegas"||state.predictions))?'opacity:.5;':'';
    const badge=has?'<span class="sys-live">●</span>':(isCore?'<span class="sys-off">no PDF data</span>':(s.code==="vegas"?'<span class="sys-off">no line yet</span>':(state.predictions?'<span class="sys-off">no data</span>':'')));
    // Custom Model # exposes editable weights for every checked system.
    // Option 2 (Sept 1 2026): this box stays visible while PickGauge Model #
    // is active too, not just in fully-custom mode -- it now controls this
    // system's contribution to Custom Blend even though it still has zero
    // effect on the pure PickGauge Model # number itself. Only genuinely
    // hidden when the system isn't checked at all.
    const wbox=on?`<input type="number" class="weight-inp sys-weight" data-w="${esc(s.code)}" step="0.5" min="0" inputmode="decimal" title="weight for ${esc(s.name)}${pgActive?' (in Custom Blend)':''}" value="${weightOf(s.code)}">`:'';
    // "★ Top 7" badge -- reinstated Sept 2, 2026 (Drew's explicit request)
    // for exactly the 7 systems in TOP_SYSTEM_RANKS (app/js/main.js).
    // Previously removed entirely (see git history) while an older
    // "Top 10" ranking existed alongside a newer, undocumented validation
    // pass; TOP_SYSTEM_RANKS has since been rebuilt as the one current,
    // documented ranking source, so it's safe to render again.
    const top=(typeof TOP_SYSTEM_RANKS!=="undefined")?TOP_SYSTEM_RANKS[s.code]:null;
    const topBadge=top?`<span class="sys-top" title="Top 7 by composite score in Drew's 2-year backtest (40% ATS% / 30% MAE / 30% |Bias|, lower composite = better)${top.composite!=null?` — composite ${top.composite}`:''}">★ Top 7</span>`:'';
    return `<div class="sys-item" style="${dim}">
      <label class="sys-check"><input type="checkbox" data-sys="${esc(s.code)}" ${on?'checked':''}><span class="sys-name">${esc(s.name)}</span>${topBadge}</label>
      <span class="sys-right">${wbox}${badge}</span>
    </div>`;
  }).join("");
  wrap.querySelectorAll("[data-sys]").forEach(cb=>cb.onchange=()=>{
    const code=cb.dataset.sys;
    const set=new Set(state.enabledSystems);
    if(cb.checked) set.add(code); else set.delete(code);
    state.enabledSystems=[...set];
    save(); renderSystemsSettings(); renderBoard(); updateSystemsCount();
  });
  wrap.querySelectorAll(".sys-weight").forEach(bindWeightInput);
  // #pdfFile now lives INSIDE this grid (see the __import_pdf__ cell above),
  // so it -- and its onchange handler -- gets destroyed and recreated on
  // every single call to this function (every checkbox toggle, weight
  // change, predictions load). Re-bind every time, same reasoning as the
  // [data-sys]/.sys-weight rebinds just above: a stale handler on an
  // orphaned old element is as good as no handler at all. This replaces
  // the ONE-TIME binding init.js used to do (removed there -- that ran
  // before this function's first-ever call within init(), so #pdfFile
  // didn't exist in the DOM yet at that point once the static markup
  // moved here, and would have thrown).
  const pdfFileEl=document.getElementById("pdfFile");
  if(pdfFileEl) pdfFileEl.onchange=e=>{ if(e.target.files[0]){ importPowers(e.target.files[0]); e.target.value=""; } };
  updateSystemsCount();
}
function updateSystemsCount(){
  const el=document.getElementById("systemsCount");
  if(el){
    const n=state.enabledSystems.length;
    el.textContent=isPickGaugeModelActive()
      ?(`PickGauge Model #${n?` + ${n} comparison${n===1?"":"s"}`:""}`)
      :(n+" on");
  }
  const meta=document.getElementById("predMetaLine");
  if(meta){
    meta.textContent=state.predMeta&&state.predMeta.fetchedAt
      ? `Last loaded ${new Date(state.predMeta.fetchedAt).toLocaleString(undefined,{month:"short",day:"numeric",hour:"numeric",minute:"2-digit"})} · ${state.predMeta.count} games`
      : "Not loaded yet.";
  }
}
